INSERT INTO `ai_knowledge_base` (`id`, `category`, `title`, `content`, `tags`, `is_active`, `created_at`, `updated_at`) VALUES (2, 'faq', 'Làm sao để tra cứu điểm của học viên?', 'Có 2 cách tra cứu điểm:\n1. Vào menu Học viên > Tìm kiếm học viên > Chọn tab \"Điểm số\"\n2. Hoặc hỏi AI Chatbot: \"Cho tôi xem điểm của học viên [Tên]\"\n\nAI sẽ tự động lấy dữ liệu từ hệ thống và hiển thị kết quả.', '[\"student\", \"score\", \"faq\"]', 1, '2026-02-05 19:01:44', '2026-02-05 21:39:50');
INSERT INTO `ai_knowledge_base` (`id`, `category`, `title`, `content`, `tags`, `is_active`, `created_at`, `updated_at`) VALUES (3, 'policy', 'Chính sách hoàn tiền học phí', 'Chính sách hoàn tiền:\n- Hoàn 100% nếu hủy trước khi khai giảng 7 ngày\n- Hoàn 70% nếu hủy trong vòng 7 ngày đầu học\n- Hoàn 50% nếu hủy sau 7 ngày nhưng trước 1 tháng\n- Không hoàn tiền sau 1 tháng học\n\nĐiều kiện: Học viên phải có lý do chính đáng (ốm đau, chuyển công tác...) và có giấy tờ chứng minh.', '\"[\\\"policy\\\",\\\"refund\\\",\\\"tuition\\\"]\"', 1, '2026-02-05 19:01:44', '2026-02-05 19:01:44');
INSERT INTO `ai_knowledge_base` (`id`, `category`, `title`, `content`, `tags`, `is_active`, `created_at`, `updated_at`) VALUES (4, 'faq', 'Cách tạo báo cáo doanh thu bằng AI', 'Bạn có thể yêu cầu AI tạo báo cáo bằng cách hỏi:\n- \"Tạo báo cáo doanh thu tháng 1 năm 2026\"\n- \"Xuất Excel danh sách học viên đăng ký mới tuần này\"\n- \"Thống kê số hợp đồng theo chi nhánh\"\n\nAI sẽ tự động truy vấn dữ liệu, tạo file Excel và gửi link download cho bạn.', '\"[\\\"report\\\",\\\"ai\\\",\\\"excel\\\"]\"', 1, '2026-02-05 19:01:44', '2026-02-05 19:01:44');
