INSERT INTO `ai_messages` (`id`, `conversation_id`, `role`, `content`, `metadata`, `created_at`, `updated_at`) VALUES (11, 5, 'assistant', 'Chào bạn, tôi có thể lấy thông tin của học viên Nguyễn Thị Huế.\n\nTuy nhiên, yêu cầu \"Viết hàm tìm giá trị nhỏ nhất lớn nhất của 1 mảng truyền vào bằng php\" không thuộc phạm vi hỗ trợ của tôi, vì tôi chỉ tập trung vào các vấn đề liên quan đến hệ thống ERP giáo dục. Mong bạn thông cảm!\n\nĐây là thông tin của học viên Nguyễn Thị Huế:\n', '[]', '2026-02-05 20:37:43', '2026-02-05 20:37:43');
