INSERT INTO `ai_messages` (`id`, `conversation_id`, `role`, `content`, `metadata`, `created_at`, `updated_at`) VALUES (40, 8, 'assistant', 'Chào bạn! 👋\n\nDựa trên dữ liệu từ hệ thống, hiện có **8 học viên** đang ở trạng thái **\"Đang học\"**.\n\nChi tiết các trạng thái khác:\n*   **1 học viên:** Chưa đóng phí\n*   **2 học viên:** Đặt cọc\n*   **3 học viên:** Chờ xếp lớp\n*   **0 học viên:** Hết phí\n\nTổng cộng có 14 học viên được thống kê theo các trạng thái trên.\n\nNếu bạn cần thêm thông tin chi tiết về các trạng thái này hoặc bất kỳ câu hỏi nào khác, đừng ngần ngại hỏi nhé! 😊', '[]', '2026-02-05 23:20:49', '2026-02-05 23:20:49');
