INSERT INTO `ai_messages` (`id`, `conversation_id`, `role`, `content`, `metadata`, `created_at`, `updated_at`) VALUES (75, 11, 'assistant', 'Tuyệt vời! Để mình lấy báo cáo doanh thu cho trung tâm Hà Đông vào tháng 3 năm 2026 nhé.\n\nTuy nhiên, mình cần mã số chi nhánh (branch_id) của trung tâm Hà Đông để có thể truy xuất dữ liệu chính xác nhất. Bạn có thể cung cấp cho mình mã số này được không? 😊', '[]', '2026-04-01 13:43:12', '2026-04-01 13:43:12');
