INSERT INTO `ai_messages` (`id`, `conversation_id`, `role`, `content`, `metadata`, `created_at`, `updated_at`) VALUES (77, 11, 'assistant', 'Mình hiểu là bạn muốn lấy doanh thu của trung tâm Hà Đông. Tuy nhiên, hệ thống của mình cần mã số chi nhánh (branch_id) chứ không phải tên chi nhánh để có thể truy xuất thông tin chính xác.\n\nBạn có thể vui lòng cung cấp giúp mình **mã số chi nhánh của trung tâm Hà Đông** được không? Khi có mã số này, mình sẽ lấy báo cáo doanh thu tháng 3 năm 2026 cho bạn ngay ạ! 😊', '[]', '2026-04-01 13:43:54', '2026-04-01 13:43:54');
