INSERT INTO `ai_messages` (`id`, `conversation_id`, `role`, `content`, `metadata`, `created_at`, `updated_at`) VALUES (102, 12, 'assistant', '', '{\"result\": {\"message\": \"❌ Không tìm thấy trung tâm nào phù hợp với từ khóa \'Hà Đông\'\", \"success\": false}, \"arguments\": {\"keyword\": \"Hà Đông\"}, \"function_called\": \"search_branches\"}', '2026-04-01 16:23:11', '2026-04-01 16:23:11');
INSERT INTO `ai_messages` (`id`, `conversation_id`, `role`, `content`, `metadata`, `created_at`, `updated_at`) VALUES (103, 12, 'assistant', 'Cảm ơn bạn đã cung cấp thời gian là **tháng 03 năm 2026**! 😊\n\nTôi đã thử tìm kiếm trung tâm \"Hà Đông\" trong hệ thống của mình để tra cứu doanh số. Tuy nhiên, rất tiếc, công cụ của tôi báo rằng:\n\n```json\n{\"success\":false,\"message\":\"❌ Không tìm thấy trung tâm nào phù hợp với từ khóa \'Hà Đông\'\"}\n```\n\nĐiều này có nghĩa là tôi **không tìm thấy trung tâm nào có tên \"Hà Đông\"** trong hệ thống ERP của chúng ta. 😥\n\nĐể tôi có thể giúp bạn tra cứu doanh số chính xác, bạn vui lòng:\n*   Kiểm tra lại tên trung tâm \"Hà Đông\" đã đúng chưa.\n*   Hoặc bạn có thể cung cấp tên chính xác của trung tâm như đã đăng ký trong hệ thống (ví dụ: \"Trung tâm Đào tạo Hà Đông 1\", \"Chi nhánh Hà Đông\").\n\nNếu bạn muốn, tôi có thể thử liệt kê danh sách các trung tâm hiện có để bạn chọn nhé!', '[]', '2026-04-01 16:23:15', '2026-04-01 16:23:15');
