INSERT INTO `ai_messages` (`id`, `conversation_id`, `role`, `content`, `metadata`, `created_at`, `updated_at`) VALUES (105, 12, 'assistant', 'Tôi hiểu rằng bạn đang tìm kiếm thông tin về trung tâm \"Hà Đông\". Rất tiếc, như tôi đã thông báo trước đó, tôi không tìm thấy trung tâm nào có tên chính xác là \"Hà Đông\" trong hệ thống của chúng ta.\n\nTuy nhiên, tôi sẽ thử tìm kiếm các trung tâm có tên gần giống với \"Hà Đông\" để xem có kết quả nào không nhé.\n\n', '[]', '2026-04-01 16:23:59', '2026-04-01 16:23:59');
