INSERT INTO `ai_messages` (`id`, `conversation_id`, `role`, `content`, `metadata`, `created_at`, `updated_at`) VALUES (177, 20, 'assistant', 'À, xin lỗi bạn vì sự nhầm lẫn vừa rồi! Cảm ơn bạn đã cung cấp lại thông tin. Tôi đã tìm thấy chi nhánh \" HA DONG\" với ID là 20 trong hệ thống. 👍\n\nBây giờ, tôi sẽ tiến hành tra cứu doanh thu của chi nhánh **HA DONG** trong **tháng 4 năm 2026** cho bạn nhé.\n\nVui lòng chờ một chút trong khi tôi truy xuất dữ liệu...\n\n---\n**Sử dụng công cụ:**\n`get_revenue_report(branch_id=20, month=4, year=2026)`', '[]', '2026-06-22 22:38:03', '2026-06-22 22:38:03');
