INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1041, 100, 'total', '5 EA', 'Học sinh có kỹ năng giải quyết vấn đề và năng lực học tập tốt. Học sinh có thể tham gia các lớp cấp độ cao hơn và thử thách bản thân bằng cách thực hành giải quyết các vấn đề khó hơn của giáo dục tài năng. Học sinh giải quyết được nhiều vấn đề không quan trọng bằng học sinh giải quyết sâu sắc một vấn đề và bằng nhiều phương pháp khác nhau.', '', '2026-05-30 02:40:07', '2026-05-30 02:40:07');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1042, 100, 'total', '4 EA', 'Học sinh có năng lực học tập tốt và khả năng giải quyết vấn đề trong các lĩnh vực khác ngoài <span class=\"co_red\">#weakUnitCdNms#</span>.', 'Kiểm tra lại xem học sinh có hiểu thấu đáo về vấn đề  <span class=\"co_red\">#weakUnitCdNms#</span> hay không.', '2026-05-30 02:40:07', '2026-05-30 02:40:07');
