INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1056, 101, 'unit', 'A', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>.  Học sinh hiểu và vận dụng kiến thức về giá trị của chữ số sẽ giúp học sinh so sánh các số tốt hơn,', '2026-05-30 02:40:09', '2026-05-30 02:40:09');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1057, 101, 'unit', 'B', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Thành thạo việc tính toán với các con số giúp học sinh xử lý tốt các bài toán đố có lời văn và tự tin hơn trong việc giải quyết các vấn đề toán học khác.', '2026-05-30 02:40:09', '2026-05-30 02:40:09');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1058, 101, 'unit', 'C', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>.  Cảm nhận về hình học và góc là điều rất quan trọng, giúp học sinh tiến gần hơn với toán học ứng dụng.', '2026-05-30 02:40:09', '2026-05-30 02:40:09');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1059, 101, 'unit', 'D', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>.  Học sinh cần luyện tập thường xuyên về việc so sánh các phân số, rút gọn phân số và thực hiện các phép tính liên quan đến phân số để giải quyết các bài toán một cách linh hoạt.', '2026-05-30 02:40:09', '2026-05-30 02:40:09');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1060, 101, 'unit', 'E', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>.  Học sinh cần luyện tập việc đọc biểu đồ và sử dụng các số liệu trong biểu đồ một cách thành thạo.', '2026-05-30 02:40:09', '2026-05-30 02:40:09');
