INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1066, 102, 'unit', 'A', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Nội dung này kiểm tra khả năng kết hợp và sử dụng các phép tính khác nhau của học sinh. Học sinh có thể giải quyết vấn đề trong nội dung này một cách chắc chắn và chính xác là rất quan trọng trong việc duy trì đam mê và hứng thú với môn Toán.', '2026-05-30 02:40:10', '2026-05-30 02:40:10');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1067, 102, 'unit', 'B', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Cảm nhận về hình học hai chiều và bước đầu quan sát, xác định các khối hình không gian là điều rất quan trọng, giúp học sinh tiến gần hơn với toán học ứng dụng.', '2026-05-30 02:40:10', '2026-05-30 02:40:10');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1068, 102, 'unit', 'C', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>.  Cần khuyến khích để học sinh hiểu và sử dụng các đơn vị đo lường hiệu quả và hợp lý hơn.', '2026-05-30 02:40:10', '2026-05-30 02:40:10');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1069, 102, 'unit', 'D', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Khả năng phân loại là nền tảng của kỹ năng suy luận toán học và rất cần thiết khi ứng dụng trong thực tế cuộc sống. ', '2026-05-30 02:40:10', '2026-05-30 02:40:10');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1070, 102, 'unit', 'E', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Đây là kiến thức cơ sở của lớp 2, kiểm tra khả năng hiểu biết của học sinh về bản chất của các phép toán và ứng dụng cho các phép toán khó hơn.', '2026-05-30 02:40:10', '2026-05-30 02:40:10');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1071, 103, 'total', '5 EA', ' Học sinh có kỹ năng giải quyết vấn đề và năng lực học tập tốt. Học sinh có thể tham gia các lớp cấp độ cao hơn và thử thách bản thân bằng cách thực hành giải quyết các vấn đề khó hơn của giáo dục tài năng. Quan trọng hơn cả việc giải quyết được nhiều vấn đề, chính là giải quyết sâu một vấn đề mà sử dụng các phương pháp khác nhau. ', '', '2026-05-30 02:40:12', '2026-05-30 02:40:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1072, 103, 'total', '4 EA', 'Có năng lực học tập tốt và khả năng giải quyết vấn đề trong các lĩnh vực khác ngoài  vấn đề<span class=\"co_red\">#weakUnitCdNms#</span>. ', 'Hỏi lại học sinh xem các con có hiểu hoàn toàn hay không về các vấn đề:  <span class=\"co_red\">#weakUnitCdNms#</span>.', '2026-05-30 02:40:12', '2026-05-30 02:40:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1073, 103, 'total', '3 EA', 'Có năng lực học tập tốt và khả năng giải quyết vấn đề trong các lĩnh vực khác ngoài <span class=\"co_red\">#weakUnitCdNms#</span>. ', 'Hỏi lại học sinh xem các con có hiểu hoàn toàn hay không về các vấn đề:  <span class=\"co_red\">#weakUnitCdNms#</span>.', '2026-05-30 02:40:12', '2026-05-30 02:40:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1074, 103, 'total', '2 EA', 'Có năng lực học tập tốt và khả năng giải quyết vấn đề trong <span class=\"co_sky\">#goodUnitCdNms#</span>.', 'Hỏi lại học sinh xem các con có hiểu hoàn toàn hay không về các vấn đề:  <span class=\"co_red\">#weakUnitCdNms#</span>.', '2026-05-30 02:40:12', '2026-05-30 02:40:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1075, 103, 'total', '1 EA', '', 'Hỏi lại học sinh xem các con có hiểu hoàn toàn hay không về các vấn đề:  <span class=\"co_red\">#weakUnitCdNms#</span>.', '2026-05-30 02:40:12', '2026-05-30 02:40:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1076, 103, 'unit', 'A', NULL, 'Học sinh cần cải thiện về  <span class=\"co_red\">#weakUnitCdNm#</span>. Phép cộng và phép trừ là kiến thức cơ bản của Toán học. Các con hiểu rõ về khái niệm này sẽ giúp hiểu những phép toán khác.', '2026-05-30 02:40:12', '2026-05-30 02:40:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1077, 103, 'unit', 'B', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Kiến thức này có tác dụng quan trọng để mở rộng khái niệm và hiểu các hình dạng chính xác hơn. Học sinh nên thực hành vẽ hình rồi đặt tên cho chúng và quan sát các đặc điểm và thuộc tính của chúng.', '2026-05-30 02:40:12', '2026-05-30 02:40:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1078, 103, 'unit', 'C', NULL, 'Học sinh cần cái thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Học sinh sẽ có thể tiếp cận các vấn đề tương tự bằng cách hiểu đầy đủ các nguyên tắc của  phép nhân và phép chia. Điều quan trọng nhất là học sinh phải hiểu mối quan hệ giữa hai khái niệm để có thể giải quyết vấn đề một cách chính xác.', '2026-05-30 02:40:12', '2026-05-30 02:40:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1079, 103, 'unit', 'D', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Phân số và số thập phân là một sự mở rộng từ hệ thống số mà học sinh đã học nên điều quan trọng là học sinh phải có một sự hiểu biết chắc chắn về sự cần thiết và cách sử dụng của các phép tính này.', '2026-05-30 02:40:12', '2026-05-30 02:40:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1080, 103, 'unit', 'E', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Điều quan trọng là học sinh có thể so sánh độ dài và có đủ hiểu biết về các đơn vị. Học sinh có thể xem và đọc thời gian một cách thuần thục. Yêu cầu học sinh thực hành kỹ năng này trong cuộc sống hàng ngày của mình.', '2026-05-30 02:40:12', '2026-05-30 02:40:12');
