INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1126, 111, 'unit', 'A', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Trong phần này, học sinh học về mối quan hệ của các con số trong các phép tính cũng như thứ tự tính toán. Từ đó học sinh có thể áp dụng linh hoạt các phép tính trong các bài toán khác nhau.', '2026-05-30 02:40:26', '2026-05-30 02:40:26');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1127, 111, 'unit', 'B', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Việc quan sát xem học sinh đã nắm rõ các nguyên tắc cộng, trừ phân số và rút gọn phân số, hỗn số hay chưa là rất quan trọng. Sau khi học sinh hiểu rõ, cần luyện tập nhiều hơn với nhiều vấn đề khó hơn.', '2026-05-30 02:40:26', '2026-05-30 02:40:26');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1128, 111, 'unit', 'C', NULL, 'Học sinh cần cải thiện trong #weakUnitCdNm#. Học sinh hiểu và vận dụng kiến thức về quy luật sẽ giúp việc dự đoán và đưa ra kết luận chính xác.', '2026-05-30 02:40:26', '2026-05-30 02:40:26');
