INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1161, 117, 'unit', 'A', NULL, 'Học sinh cần cải thiện về  #weakUnitCdNm#. Các số đến 9 là kiến thức cơ bản của Toán học.  Hiểu rõ bản chất và mối quan hệ của các số đến 9 sẽ giúp con học dễ dàng những số lớn hơn.', '2026-05-30 02:40:36', '2026-05-30 02:40:36');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1162, 117, 'unit', 'B', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Kiến thức này có tác dụng quan trọng để mở rộng khái niệm và hiểu các hình dạng chính xác hơn. Học sinh nên thực hành vẽ hình rồi đặt tên cho chúng và quan sát các đặc điểm và thuộc tính của chúng.', '2026-05-30 02:40:36', '2026-05-30 02:40:36');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1163, 117, 'unit', 'C', NULL, 'Học sinh cần cải thiện về  #weakUnitCdNm#. Phép cộng và phép trừ là kiến thức cơ bản của Toán học. Các con hiểu rõ về khái niệm này sẽ giúp hiểu những phép toán khác.', '2026-05-30 02:40:36', '2026-05-30 02:40:36');
