INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1171, 118, 'unit', 'A', NULL, 'Học sinh cần cải thiện về  #weakUnitCdNm#. Các số đến 9 là kiến thức cơ bản của Toán học.  Hiểu rõ bản chất và mối quan hệ của các số đến 9 sẽ giúp con học dễ dàng những số lớn hơn.', '2026-05-30 02:40:38', '2026-05-30 02:40:38');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1172, 118, 'unit', 'B', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Kiến thức này có tác dụng quan trọng để mở rộng khái niệm và hiểu các hình dạng chính xác hơn. Học sinh nên thực hành vẽ hình rồi đặt tên cho chúng và quan sát các đặc điểm và thuộc tính của chúng.', '2026-05-30 02:40:38', '2026-05-30 02:40:38');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1173, 118, 'unit', 'C', NULL, 'Học sinh cần cải thiện về  #weakUnitCdNm#. Phép cộng và phép trừ là kiến thức cơ bản của Toán học. Các con hiểu rõ về khái niệm này sẽ giúp hiểu những phép toán khác.', '2026-05-30 02:40:38', '2026-05-30 02:40:38');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1174, 118, 'unit', 'D', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Học sinh cần nắm được đặc điểm của từng đối tượng, từ đó nhận biết được đặc điểm chung và tiêu chí để so sánh.', '2026-05-30 02:40:38', '2026-05-30 02:40:38');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1175, 118, 'unit', 'E', NULL, 'Học sinh cần cải thiện về  #weakUnitCdNm#. Các số đến 50 là một thách thức đối với một số bạn nhưng là cơ sở để con tiếp cận những kiến thức khó hơn.', '2026-05-30 02:40:38', '2026-05-30 02:40:38');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1176, 119, 'total', '5 EA', 'Học sinh có kỹ năng giải quyết vấn đề và năng lực học tập tốt. Học sinh có thể tham gia các lớp cấp độ cao hơn và thử thách bản thân bằng cách thực hành giải quyết các vấn đề khó hơn của giáo dục tài năng. Quan trọng hơn cả việc giải quyết được nhiều vấn đề, chính là giải quyết sâu một vấn đề mà sử dụng các phương pháp khác nhau.', '', '2026-05-30 02:40:40', '2026-05-30 02:40:40');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1177, 119, 'total', '4 EA', 'Có năng lực học tập tốt và khả năng giải quyết vấn đề trong các lĩnh vực khác ngoài  vấn đề<span class=\"co_red\">#weakUnitCdNms#</span>.', 'Hỏi lại học sinh xem các con có hiểu hoàn toàn hay không về các vấn đề:  <span class=\"co_red\">#weakUnitCdNms#</span>.', '2026-05-30 02:40:40', '2026-05-30 02:40:40');
