INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1191, 120, 'unit', 'A', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>.  Học sinh cần nắm rõ các các công thức tính chu vi và diện tích và vận dụng chúng một cách linh hoạt để giải quyết các bài toán.', '2026-05-30 02:40:42', '2026-05-30 02:40:42');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1192, 120, 'unit', 'B', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Thành thạo việc tính toán với các con số giúp học sinh xử lý tốt các bài toán đố có lời văn và tự tin hơn trong việc giải quyết các vấn đề toán học khác.', '2026-05-30 02:40:42', '2026-05-30 02:40:42');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1193, 120, 'unit', 'C', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>.  Cảm nhận về hình học và góc là điều rất quan trọng, giúp học sinh tiến gần hơn với toán học ứng dụng.', '2026-05-30 02:40:42', '2026-05-30 02:40:42');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1194, 120, 'unit', 'D', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>.  Học sinh cần luyện tập thường xuyên về việc so sánh các phân số, rút gọn phân số và thực hiện các phép tính liên quan đến phân số để giải quyết các bài toán một cách linh hoạt.', '2026-05-30 02:40:42', '2026-05-30 02:40:42');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1195, 120, 'unit', 'E', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>.  Học sinh cần nắm vững quy tắc quy đổi của các đơn vị đo lường nhằm giải quyết linh hoạt các bài toán.', '2026-05-30 02:40:42', '2026-05-30 02:40:42');
