INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1206, 122, 'unit', 'A', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Trong phần này, học sinh học về mối quan hệ của các con số trong các phép tính cũng như thứ tự tính toán. Từ đó học sinh có thể áp dụng linh hoạt các phép tính trong các bài toán khác nhau.', '2026-05-30 02:40:46', '2026-05-30 02:40:46');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1207, 122, 'unit', 'B', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Việc quan sát xem học sinh đã nắm rõ các nguyên tắc cộng, trừ phân số và rút gọn phân số, hỗn số hay chưa là rất quan trọng. Sau khi học sinh hiểu rõ, cần luyện tập nhiều hơn với nhiều vấn đề khó hơn.', '2026-05-30 02:40:46', '2026-05-30 02:40:46');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1208, 122, 'unit', 'C', NULL, 'Học sinh cần cải thiện trong #weakUnitCdNm#. Học sinh hiểu và vận dụng kiến thức về quy luật sẽ giúp việc dự đoán và đưa ra kết luận chính xác.', '2026-05-30 02:40:46', '2026-05-30 02:40:46');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1209, 122, 'unit', 'D', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Hình học không gian sẽ phức tạp hơn vì vậy cần cho học sinh luyện tập với các vật thật để hiểu rõ đặc điểm của chúng.', '2026-05-30 02:40:46', '2026-05-30 02:40:46');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1210, 122, 'unit', 'E', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Việc để học sinh  khám phá ra cách tính các diện tích của các hình đa giác và các nguyên tắc đằng sau nó là rất quan trọng. Học sinh cần hiểu tại sao diện tích lại được tính theo cách đó và việc hiểu bản chất quan trọng hơn việc ghi nhớ các công thức tính diện tích.', '2026-05-30 02:40:46', '2026-05-30 02:40:46');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1211, 123, 'total', '5 EA', 'Học sinh có kỹ năng giải quyết vấn đề và năng lực học tập tốt. Học sinh có thể tham gia các lớp cấp độ cao', '', '2026-05-30 02:40:47', '2026-05-30 02:40:47');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1212, 123, 'total', '4 EA', 'Có năng lực học tập tốt và khả năng giải quyết vấn đề trong các lĩnh vực khác ngoài  vấn đề<span class=\"co_red\">#weakUnitCdNms#</span>.', 'Chưa chắc chắn về khả năng hiểu hoàn toàn của học sinh về các vấn đề:  <span class=\"co_red\">#weakUnitCdN', '2026-05-30 02:40:47', '2026-05-30 02:40:47');
