INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1238, 125, 'unit', 'C', NULL, 'Học sinh cần cái thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Học sinh sẽ có thể tiếp cận các vấn đề tương tự bằng cách hiểu đầy đủ các nguyên tắc của  phép nhân và phép chia. Điều quan trọng nhất là học sinh phải hiểu mối quan hệ giữa hai khái niệm để có thể giải quyết vấn đề một cách chính xác.', '2026-05-30 02:40:50', '2026-05-30 02:40:50');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1239, 125, 'unit', 'D', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Học sinh cần nắm được những thông tin có trong biểu đồ, hiểu cách thống kê theo các tiêu chí của biểu đồ và cách sử dụng các thông tin đó.', '2026-05-30 02:40:50', '2026-05-30 02:40:50');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1240, 125, 'unit', 'E', NULL, 'Học sinh cần cải thiện về <span class=\"co_red\">#weakUnitCdNm#</span>. Điều quan trọng là học sinh có thể so sánh độ dài và có đủ hiểu biết về các đơn vị. Học sinh có thể xem và đọc thời gian một cách thuần thục. Yêu cầu học sinh thực hành kỹ năng này trong cuộc sống hàng ngày của mình.', '2026-05-30 02:40:50', '2026-05-30 02:40:50');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1241, 126, 'total', '5 EA', 'Học sinh có kỹ năng giải quyết vấn đề và năng lực học tập tốt. Học sinh có thể tham gia các lớp cấp độ cao hơn và thử thách bản thân bằng cách thực hành giải quyết các vấn đề khó hơn của giáo dục tài năng. Học sinh giải quyết được nhiều vấn đề không quan trọng bằng học sinh giải quyết sâu sắc một vấn đề và bằng nhiều phương pháp khác nhau.', '', '2026-05-30 02:40:53', '2026-05-30 02:40:53');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1242, 126, 'total', '4 EA', 'Học sinh có năng lực học tập tốt và khả năng giải quyết vấn đề trong các lĩnh vực khác ngoài #weakUnitCdNms#.', 'Kiểm tra lại xem học sinh có hiểu thấu đáo về vấn đề  #weakUnitCdNms# hay không.', '2026-05-30 02:40:53', '2026-05-30 02:40:53');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1243, 126, 'total', '3 EA', 'Học sinh có năng lực học tập tốt và khả năng giải quyết vấn đề trong các lĩnh vực khác ngoài #weakUnitCdNms#.', 'Kiểm tra lại xem học sinh có hiểu thấu đáo về vấn đề #weakUnitCdNms# hay không.', '2026-05-30 02:40:53', '2026-05-30 02:40:53');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1244, 126, 'total', '2 EA', 'Học sinh có năng lực học tập tốt và khả năng giải quyết vấn đề trong  lĩnh vực  #goodUnitCdNms#.', 'Kiểm tra lại xem học sinh có hiểu thấu đáo về vấn đề #weakUnitCdNms# hay không.', '2026-05-30 02:40:53', '2026-05-30 02:40:53');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1245, 126, 'total', '1 EA', '', 'Kiểm tra lại xem học sinh có hiểu về vấn đề #weakUnitCdNms# hay không.', '2026-05-30 02:40:53', '2026-05-30 02:40:53');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1246, 126, 'unit', 'A', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#.  Học sinh cần nắm rõ các các công thức tính chu vi và diện tích và vận dụng chúng một cách linh hoạt để giải quyết các bài toán.', '2026-05-30 02:40:53', '2026-05-30 02:40:53');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1247, 126, 'unit', 'B', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Thành thạo việc tính toán với các con số giúp học sinh xử lý tốt các bài toán đố có lời văn và tự tin hơn trong việc giải quyết các vấn đề toán học khác.', '2026-05-30 02:40:53', '2026-05-30 02:40:53');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1248, 126, 'unit', 'C', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#.  Cảm nhận về hình học và góc là điều rất quan trọng, giúp học sinh tiến gần hơn với toán học ứng dụng.', '2026-05-30 02:40:53', '2026-05-30 02:40:53');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1249, 126, 'unit', 'D', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#.  Học sinh cần luyện tập thường xuyên về việc so sánh các phân số, rút gọn phân số và thực hiện các phép tính liên quan đến phân số để giải quyết các bài toán một cách linh hoạt.', '2026-05-30 02:40:53', '2026-05-30 02:40:53');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1250, 126, 'unit', 'E', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#.  Học sinh cần nắm vững quy tắc quy đổi của các đơn vị đo lường nhằm giải quyết linh hoạt các bài toán.', '2026-05-30 02:40:53', '2026-05-30 02:40:53');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1251, 127, 'total', '5 EA', 'Học sinh có kỹ năng giải quyết vấn đề và năng lực học tập tốt. Học sinh có thể tham gia các lớp cấp độ cao hơn và thử thách bản thân bằng cách thực hành giải quyết các vấn đề khó hơn của giáo dục tài năng. Quan trọng hơn cả việc giải quyết được nhiều vấn đề, chính là giải quyết sâu một vấn đề mà sử dụng các phương pháp khác nhau.', '', '2026-05-30 02:40:57', '2026-05-30 02:40:57');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1252, 127, 'total', '4 EA', 'Có năng lực học tập tốt và khả năng giải quyết vấn đề trong các lĩnh vực khác ngoài #weakUnitCdNms#.', 'Yêu cầu học sinh kiểm tra xem họ có hiểu hoàn toàn hay không #weakUnitCdNms#.', '2026-05-30 02:40:57', '2026-05-30 02:40:57');
