INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1346, 136, 'unit', 'A', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#.  Học sinh cần nắm rõ các các công thức tính chu vi và diện tích và vận dụng chúng một cách linh hoạt để giải quyết các bài toán.', '2026-05-30 02:41:10', '2026-05-30 02:41:10');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1347, 136, 'unit', 'B', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#.  Cảm nhận về hình học và góc là điều rất quan trọng, giúp học sinh tiến gần hơn với toán học ứng dụng.', '2026-05-30 02:41:10', '2026-05-30 02:41:10');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1348, 136, 'unit', 'C', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Thành thạo việc tính toán với các con số giúp học sinh xử lý tốt các bài toán đố có lời văn và tự tin hơn trong việc giải quyết các vấn đề toán học khác.', '2026-05-30 02:41:10', '2026-05-30 02:41:10');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1349, 136, 'unit', 'D', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#.  Học sinh cần luyện tập thường xuyên về việc so sánh các phân số, rút gọn phân số và thực hiện các phép tính liên quan đến phân số để giải quyết các bài toán một cách linh hoạt.', '2026-05-30 02:41:10', '2026-05-30 02:41:10');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1350, 136, 'unit', 'E', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#.  Học sinh cần nắm vững quy tắc quy đổi của các đơn vị đo lường nhằm giải quyết linh hoạt các bài toán.', '2026-05-30 02:41:10', '2026-05-30 02:41:10');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1351, 137, 'total', '5 EA', 'Học sinh có kỹ năng giải quyết vấn đề và năng lực học tập tốt. Học sinh có thể tham gia các lớp cấp độ cao hơn và thử thách bản thân bằng cách thực hành giải quyết các vấn đề khó hơn của giáo dục tài năng. Quan trọng hơn cả việc giải quyết được nhiều vấn đề, chính là giải quyết sâu một vấn đề mà sử dụng các phương pháp khác nhau.', '', '2026-05-30 02:41:12', '2026-05-30 02:41:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1352, 137, 'total', '4 EA', 'Có năng lực học tập tốt và khả năng giải quyết vấn đề trong các lĩnh vực khác ngoài #weakUnitCdNms#.', 'Yêu cầu học sinh kiểm tra xem họ có hiểu hoàn toàn hay không #weakUnitCdNms#.', '2026-05-30 02:41:12', '2026-05-30 02:41:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1353, 137, 'total', '3 EA', 'Có năng lực học tập tốt và khả năng giải quyết vấn đề trong các lĩnh vực khác ngoài #weakUnitCdNms#.', 'Yêu cầu học sinh kiểm tra xem họ có hiểu hoàn toàn hay không #weakUnitCdNms#.', '2026-05-30 02:41:12', '2026-05-30 02:41:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1354, 137, 'total', '2 EA', 'Có năng lực học tập tốt và khả năng giải quyết vấn đề trong #goodUnitCdNms#.', 'Yêu cầu học sinh kiểm tra xem họ có hiểu hoàn toàn hay không #weakUnitCdNms#.', '2026-05-30 02:41:12', '2026-05-30 02:41:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1355, 137, 'total', '1 EA', '', 'Yêu cầu học sinh kiểm tra xem họ có hiểu hoàn toàn hay không #weakUnitCdNms#.', '2026-05-30 02:41:12', '2026-05-30 02:41:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1356, 137, 'unit', 'A', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Trong phần này, học sinh học về mối quan hệ của các con số trong các phép tính cũng như thứ tự tính toán. Từ đó học sinh có thể áp dụng linh hoạt các phép tính trong các bài toán khác nhau.', '2026-05-30 02:41:12', '2026-05-30 02:41:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1357, 137, 'unit', 'B', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Hình học không gian sẽ phức tạp hơn vì vậy cần cho học sinh luyện tập với các vật thật để hiểu rõ đặc điểm của chúng.', '2026-05-30 02:41:12', '2026-05-30 02:41:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1358, 137, 'unit', 'C', NULL, 'Học sinh cần cải thiện trong #weakUnitCdNm#. Học sinh hiểu và vận dụng kiến thức về quy luật sẽ giúp việc dự đoán và đưa ra kết luận chính xác.', '2026-05-30 02:41:12', '2026-05-30 02:41:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1359, 137, 'unit', 'D', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Việc quan sát xem học sinh đã nắm rõ các nguyên tắc cộng, trừ phân số và rút gọn phân số, hỗn số hay chưa là rất quan trọng. Sau khi học sinh hiểu rõ, cần luyện tập nhiều hơn với nhiều vấn đề khó hơn.', '2026-05-30 02:41:12', '2026-05-30 02:41:12');
INSERT INTO `igbh_test_comments` (`id`, `test_seq`, `comment_type`, `condition_value`, `good_comment`, `weak_comment`, `created_at`, `updated_at`) VALUES (1360, 137, 'unit', 'E', NULL, 'Học sinh cần cải thiện về #weakUnitCdNm#. Việc để học sinh  khám phá ra cách tính các diện tích của các hình đa giác và các nguyên tắc đằng sau nó là rất quan trọng. Học sinh cần hiểu tại sao diện tích lại được tính theo cách đó và việc hiểu bản chất quan trọng hơn việc ghi nhớ các công thức tính diện tích.', '2026-05-30 02:41:12', '2026-05-30 02:41:12');
