) ENGINE=InnoDB AUTO_INCREMENT=150 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of igbh_tests
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for igbh_weekly_eval_details
-- ----------------------------
DROP TABLE IF EXISTS `igbh_weekly_eval_details`;
CREATE TABLE `igbh_weekly_eval_details` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `weekly_eval_id` bigint unsigned NOT NULL,
  `student_id` int unsigned DEFAULT NULL COMMENT 'FK trỏ tới students.id',
  `stu_seq` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Mã học sinh gốc',
  `stu_nm` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tên học sinh',
  `workbook` int NOT NULL DEFAULT '0' COMMENT 'Sách bài tập (1~20)',
  `attd_listen` int NOT NULL DEFAULT '5' COMMENT 'Khả năng lắng nghe (1~5)',
  `attd_join` int NOT NULL DEFAULT '5' COMMENT 'Tham gia bài học (1~5)',
  `attd_express` int NOT NULL DEFAULT '5' COMMENT 'Khả năng thể hiện (1~5)',
  `attd_coop` int NOT NULL DEFAULT '5' COMMENT 'Sự hợp tác (1~5)',
  `detect_normal` int NOT NULL DEFAULT '5' COMMENT 'Kỹ năng cơ bản (1~5)',
  `detect_leadersh` int NOT NULL DEFAULT '5' COMMENT 'Khả năng lãnh đạo (1~5)',
  `detect_math` int NOT NULL DEFAULT '5' COMMENT 'Khả năng toán học (1~5)',
  `detect_creative` int NOT NULL DEFAULT '5' COMMENT 'Tính sáng tạo (1~5)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `igbh_weekly_eval_details_weekly_eval_id_student_id_index` (`weekly_eval_id`,`student_id`),
  KEY `igbh_weekly_eval_details_student_id_index` (`student_id`),
  CONSTRAINT `igbh_weekly_eval_details_weekly_eval_id_foreign` FOREIGN KEY (`weekly_eval_id`) REFERENCES `igbh_weekly_evals` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of igbh_weekly_eval_details
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for igbh_weekly_evals
-- ----------------------------
DROP TABLE IF EXISTS `igbh_weekly_evals`;
CREATE TABLE `igbh_weekly_evals` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `test_seq` int NOT NULL COMMENT 'Bài kiểm tra summative',
  `class_id` int unsigned DEFAULT NULL COMMENT 'FK trỏ tới classes.id',
  `branch_id` int unsigned DEFAULT NULL COMMENT 'FK trỏ tới branches.id',
  `teacher_id` bigint unsigned DEFAULT NULL COMMENT 'FK trỏ tới users.id',
  `class_seq` int NOT NULL COMMENT 'Mã lớp CMS/LMS',
  `class_nm` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tên lớp',
  `each_cd` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Mã tuần (EC001..EC012)',
  `each_cd_nm` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tên tuần',
  `teacher_nm` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tên giáo viên',
  `eval_ymd` date DEFAULT NULL COMMENT 'Ngày kiểm tra',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Draft' COMMENT 'Draft, Completed',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `igbh_weekly_evals_test_seq_class_seq_each_cd_unique` (`test_seq`,`class_seq`,`each_cd`),
  KEY `igbh_weekly_evals_class_id_index` (`class_id`),
  KEY `igbh_weekly_evals_branch_id_index` (`branch_id`),
  KEY `igbh_weekly_evals_teacher_id_index` (`teacher_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of igbh_weekly_evals
-- ----------------------------
BEGIN;
COMMIT;

