  `status` tinyint DEFAULT NULL,
  `stt` int DEFAULT NULL,
  `product_id` int NOT NULL,
  PRIMARY KEY (`id`,`product_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

